package com.learnspherex.payment;
import java.math.*; import java.time.*; import java.util.*; import jakarta.persistence.*; import lombok.*;
@Entity @Table(name="fee_plans") @Getter @NoArgsConstructor @EqualsAndHashCode(of="id") public class FeePlan { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private Long courseId; @Column(nullable=false,length=120) private String name; @Column(nullable=false,precision=12,scale=2) private BigDecimal totalAmount; @Column(nullable=false) private boolean active=true; private Instant createdAt; @OneToMany(mappedBy="feePlan",cascade=CascadeType.ALL,orphanRemoval=true) private List<Installment> installments=new ArrayList<>(); public FeePlan(Long c,String n,BigDecimal a){courseId=c;name=n;totalAmount=a;} @PrePersist void now(){createdAt=Instant.now();} public void addInstallment(Installment i){installments.add(i);} }
